UPDATE MST_CALENDAR_INFO as A, ( select CALENDAR_ID, CALENDAR_NAME, OTHER_ID, IS_TRADE_CALENDAR, REMARK, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME from ( select TEMP.* from (
SELECT #{item.calendarId,jdbcType=CHAR} CALENDAR_ID, #{item.calendarName,jdbcType=VARCHAR} CALENDAR_NAME, #{item.otherId,jdbcType=VARCHAR} OTHER_ID, #{item.isTradeCalendar,jdbcType=VARCHAR} IS_TRADE_CALENDAR, #{item.remark,jdbcType=VARCHAR} REMARK, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, #{item.createTime,jdbcType=TIMESTAMP} CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} UPDATE_TIME FROM dual
) TEMP ) de ) AS B set A.CALENDAR_NAME = B.CALENDAR_NAME, A.OTHER_ID = B.OTHER_ID, A.IS_TRADE_CALENDAR = B.IS_TRADE_CALENDAR, A.REMARK = B.REMARK, A.CREATE_USER = B.CREATE_USER, A.CREATE_DEPT = B.CREATE_DEPT, A.CREATE_TIME = B.CREATE_TIME, A.UPDATE_USER = B.UPDATE_USER, A.UPDATE_TIME = B.UPDATE_TIME where A.CALENDAR_ID = B.CALENDAR_ID; insert into MST_CALENDAR_INFO(CALENDAR_ID, CALENDAR_NAME, OTHER_ID, IS_TRADE_CALENDAR, REMARK, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) select CALENDAR_ID, CALENDAR_NAME, OTHER_ID, IS_TRADE_CALENDAR, REMARK, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME from ( select TEMP.* from (
SELECT #{item.calendarId,jdbcType=CHAR} CALENDAR_ID, #{item.calendarName,jdbcType=VARCHAR} CALENDAR_NAME, #{item.otherId,jdbcType=VARCHAR} OTHER_ID, #{item.isTradeCalendar,jdbcType=VARCHAR} IS_TRADE_CALENDAR, #{item.remark,jdbcType=VARCHAR} REMARK, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, #{item.createTime,jdbcType=TIMESTAMP} CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} UPDATE_TIME FROM dual
) TEMP where not exists (select 1 from MST_CALENDAR_INFO CII where CII.CALENDAR_ID = TEMP.CALENDAR_ID) ) de ;
